        {
            const int bRow0 = t * BLOCK_DIM + ty * REG_TILE;
            const int bCol = outCol;
            sB[ty * REG_TILE][tx * REG_TILE] =
                (bRow0 < N && bCol < N) ? B[bRow0 * N + bCol] : 0.0f;
