        __syncthreads();

        // Compute 2x2 outputs
        for (int k = 0; k < BLOCK_DIM; ++k) {
#pragma unroll
            for (int r = 0; r < REG_TILE; ++r) {
#pragma unroll
                for (int c = 0; c < REG_TILE; ++c) {
                    acc[r][c] += sA[ty * REG_TILE + r][k] * sB[k][tx * REG_TILE + c];
                }
            }
        }

        __syncthreads();
    }

    // Store 2x2 outputs
#pragma unroll
    for (int r = 0; r < REG_TILE; ++r) {
        const int row = outRow + r;
        if (row < N) {
#pragma unroll
            for (int c = 0; c < REG_TILE; ++c) {
