#include "gemm.cuh"

#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86)
// 
// 32x32 thread block with register tiling (2x2 outputs per thread).
// Each block handles a 64x64 output tile.
// Grid: ceil(N/64) x ceil(N/64)
//
// Shared memory: 64x64 tiles with padding
// Coalesced loads, register tiling, unrolled loops
// ============================================================================

#define BLOCK_ROWS 32
#define BLOCK_COLS 32
#define REG_M 2  // Register tiling in M (rows)
#define REG_N 2  // Register tiling in N (cols)
#define TILE_ROWS BLOCK_ROWS * REG_M  // 64
#define TILE_COLS BLOCK_COLS * REG_N  // 64

__global__ void gemmKernel(const float* A, const float* B, float* C, int N) {
    // Shared memory tiles padded for bank conflict avoidance
    __shared__ float sA[TILE_ROWS][TILE_COLS + 1];
    __shared__ float sB[TILE_ROWS + 1][TILE_COLS];

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int bx = blockIdx.x;
    const int by = blockIdx.y;

    const int outRow = by * TILE_ROWS + ty * REG_M;
    const int outCol = bx * TILE_COLS + tx * REG_N;

    const int numTiles = (N + TILE_COLS - 1) / TILE_COLS;

    // Register accumulators: REG_M x REG_N = 2x2
    float acc[REG_M][REG_N];
#pragma unroll
    for (int r = 0; r < REG_M; ++r)
#pragma unroll
        for (int c = 0; c < REG_N; ++c)
            acc[r][c] = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        // Load A tile
        {
            const int aRow = outRow;
            const int aCol0 = t * TILE_COLS + tx * REG_N;
            sA[ty * REG_M][tx * REG_N] =
                (aRow < N && aCol0 < N) ? A[aRow * N + aCol0] : 0.0f;
            if (REG_N > 1 && aCol0 + 1 < N)
                sA[ty * REG_M][tx * REG_N + 1] =
                    A[aRow * N + aCol0 + 1];
            if (REG_M > 1 && aRow + 1 < N) {
                if (aCol0 < N)
                    sA[ty * REG_M + 1][tx * REG_N] =
                        A[(aRow + 1) * N + aCol0];
                if (aCol0 + 1 < N)
                    sA[ty * REG_M + 1][tx * REG_N + 1] =
                        A[(aRow + 1) * N + aCol0 + 1];
            }
        }

        // Load B tile
        {
            const int bRow0 = t * TILE_COLS + ty * REG_M;
            const int bCol = outCol;
