#include <cuda_runtime.h>

// ============================================================================
// Register-tiled GEMM for NVIDIA Ampere (sm_86)
// 
// 16x16 thread block with 2x2 register tiling per thread
// Each block handles a 32x32 output tile
// Each thread computes 4 output elements (2 rows x 2 cols)
// Each thread writes 4 elements to shared memory
// Shared memory: 32x32 tiles with padding
// ============================================================================

#define BLOCK_DIM 16
#define REG 2  // 2x2 register tiling

__global__ void gemmKernel(const float* A, const float* B, float* C, int N) {
    const int T = BLOCK_DIM * REG;  // 32

    __shared__ float sA[T][T + 1];
    __shared__ float sB[T + 1][T];

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int bx = blockIdx.x;
    const int by = blockIdx.y;

    const int outRow = by * T + ty * REG;
    const int outCol = bx * T + tx * REG;

    const int numTiles = (N + T - 1) / T;

    float acc[REG][REG];
#pragma unroll
    for (int r = 0; r < REG; ++r)
#pragma unroll
        for (int c = 0; c < REG; ++c)
            acc[r][c] = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        // Load A: thread (ty, tx) writes 2x2 block to sA
        // sA[ty*REG + r][tx*REG + c] = A[outRow + r][t*T + tx*REG + c]
        {
            const int aRow = outRow;
            const int aCol0 = t * T + tx * REG;
            sA[ty * REG][tx * REG] = (aRow < N && aCol0 < N) ? A[aRow * N + aCol0] : 0.0f;
            sA[ty * REG][tx * REG + 1] = (aRow < N && aCol0 + 1 < N) ? A[aRow * N + aCol0 + 1] : 0.0f;
            sA[ty * REG + 1][tx * REG] = (aRow + 1 < N && aCol0 < N) ? A[(aRow + 1) * N + aCol0] : 0.0f;
            sA[ty * REG + 1][tx * REG + 1] = (aRow + 1 < N && aCol0 + 1 < N) ? A[(aRow + 1) * N + aCol0 + 1] : 0.0f;
        }

        // Load B: thread (ty, tx) writes 2x2 block to sB
        // sB[ty*REG + r][tx*REG + c] = B[t*T + ty*REG + r][outCol + c]
        {
            const int bRow0 = t * T + ty * REG;
            const int bCol = outCol;
            sB[ty * REG][tx * REG] = (bRow0 < N && bCol < N) ? B[bRow0 * N + bCol] : 0.0f;
            sB[ty * REG + 1][tx * REG] = (bRow0 + 1 < N && bCol < N) ? B[(bRow0 + 1) * N + bCol] : 0.0f;
            sB[ty * REG][tx * REG + 1] = (bRow0 < N && bCol + 1 < N) ? B[bRow0 * N + bCol + 1] : 0.0f;
            sB[ty * REG + 1][tx * REG + 1] = (bRow0 + 1 < N && bCol + 1 < N) ? B[(bRow0 + 1) * N + bCol + 1] : 0.0f;
        }

        __syncthreads();

        // Compute 2x2 outputs
        for (int k = 0; k < T; ++k) {
#pragma unroll
            for (int r = 0; r < REG; ++r) {
#pragma unroll
                for (int c = 0; c < REG; ++c) {
                    acc[r][c] += sA[ty * REG + r][k] * sB[k][tx * REG + c];
                }
            }
        }

        __syncthreads();
    }

#pragma unroll
    for (int r = 0; r < REG; ++r) {
        const int row = outRow + r;
        if (row < N) {
#pragma unroll
            for (int c = 0; c < REG; ++c) {
                const int col = outCol + c;
                if (col < N) {
                    C[row * N + col] = acc[r][c];
                }
            }
        }
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    const int T = BLOCK_DIM * REG;
    const int gridDim = (N + T - 1) / T;
    dim3 block(BLOCK_DIM, BLOCK_DIM);
    dim3 grid(gridDim, gridDim);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
ENDOFFILE
echo "Written""}

