#include "gemm.cuh"

#include <cuda_runtime.h>
#include <mma.h>

using namespace nvcuda;

// ============================================================================
// WMMA (Tensor Core) GEMM for NVIDIA Ampere (sm_86)
// 
// Uses wmma API for 16x16x16 FP32 matrix multiply.
// Each warp handles a 16x16 output tile.
// Block has 4 warps = 4 warps collaborating on 32x32 output tile.
// ============================================================================

#define WMMA_M 16
#define WMMA_N 16
#define WMMA_K 16

#define WARPS_PER_BLOCK 4
#define BLOCK_SIZE (WARPS_PER_BLOCK * 32)

__global__ void gemmKernel(const float* A, const float* B, float* C, int N) {
    // WMMA fragment types for 16x16x16 FP32
    // wmma::matrix_a: 16 rows x 8 cols (row-major)
    // wmma::matrix_b: 8 rows x 16 cols (row-major)
    // wmma::accumulator: 16 rows x 16 cols (row-major)

