#define BLOCK_DIM 16
#define REG 4
#define TILE (BLOCK_DIM * REG)  // 64
#define DB 2  // double buffering

__global__ void gemmKernel(const float* A, const float* B, float* C, int N) {
    __shared__ float sA[DB][TILE][TILE + 1];
    __shared__ float sB[DB][TILE + 1][TILE];

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int bx = blockIdx.x;
    const int by = blockIdx.y;

    const int outRow = by * TILE + ty * REG;
    const int outCol = bx * TILE + tx * REG;

    const int numTiles = (N + TILE - 1) / TILE;

    float acc[REG][REG];
#pragma unroll
    for (int r = 0; r < REG; ++r)
#pragma unroll
        for (int c = 0; c < REG; ++c)
            acc[r][c] = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        int buf = t % DB;
        int prevBuf = (t + 1) % DB;  // buffer for the PREVIOUS tile

        // Load tile t into buffer buf
        {
            const int aRow = outRow;
            const int aCol0 = t * TILE + tx * REG;
#pragma unroll
            for (int r = 0; r < REG; ++r) {
                const int row = aRow + r;
#pragma unroll
                for (int c = 0; c < REG; ++c) {
                    const int col = aCol0 + c;
                    sA[buf][ty * REG + r][tx * REG + c] =
                        (row < N && col < N) ? A[row * N + col] : 0.0f;
                }
            }
        }
        {
            const int bRow0 = t * TILE + ty * REG;
            const int bCol = outCol;
#pragma unroll
            for (int r = 0; r < REG; ++r) {
                const int row = bRow0 + r;
#pragma unroll
                for (int c = 0; c < REG; ++c) {
                    const int col = bCol + c;
                    sB[buf][ty * REG + r][tx * REG + c] =
                        (row < N && col < N) ? B[row * N + col] : 0.0f;
                }
            }
        }

        if (t > 0) {
            // Previous buffer (prevBuf) now holds the previously computed tile
            // Compute it while loading the current tile
#pragma unroll
            for (int k = 0; k < TILE; ++k) {
#pragma unroll
                for (int r = 0; r < REG; ++r) {
#pragma unroll
                    for (int c = 0; c < REG; ++c) {
                        acc[r][c] += sA[prevBuf][ty * REG + r][k] * sB[prevBuf][k][tx * REG + c];
