#include "gemm.cuh"

#include <cuda_runtime.h>
#include <mma.h>

using namespace nvcuda;

// ============================================================================
// WMMA GEMM for NVIDIA Ampere (sm_86)
// 1 warp per block, 16x16 output per warp
// Uses wmma::mma_sync for tensor core operations
// ============================================================================

#define WMMA_M 16
#define WMMA_N 16
#define WMMA_K 16

__global__ void gemmKernel(const float* A, const float* B, float* C, int N) {
    // Each warp handles one 16x16 output tile
    int warpId = threadIdx.x / 32;
    int laneId = threadIdx.x % 32;
    int warp0 = (threadIdx.x & ~31);  // thread ID of lane 0 in this warp

    // For our case, each block has 1 warp (32 threads)
    // Each warp handles one 16x16 tile
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int outRow = by * WMMA_M + warp0;
    int outCol = bx * WMMA_N;

