#pragma unroll
                for (int c = 0; c < REG; ++c) {
                    acc[r][c] += sA[ty * REG + r][k] * sB[k][tx * REG + c];
                }
            }
        }

        __syncthreads();
    }

#pragma unroll
    for (int r = 0; r < REG; ++r) {
